class DecisionTreeCache:
    def __init__(self, max_size=10000):
        self.cache = LRUCache(max_size)
        self.hits = 0
        self.misses = 0

    def get(self, key):
        if key in self.cache:
            self.hits += 1
            return self.cache[key]
        self.misses += 1
        return None

    def set(self, key, value):
        self.cache[key] = value
